#!/usr/bin/env bash
# Reproduce the real-validation numbers of 'r3' (model-v2x-track/routed-g6) from the checkpoints: realval-A/B inference of every used
# member with its committed post-processing, bag fusion, merge with model.yaml, official metric, comparison with
# validation/results/scorecard.json. Needs the prepared real validation data and the checkpoints. Generated by
# common/tools/reproduce_validation.py. Run on an idle GPU:
#   CUDA_VISIBLE_DEVICES=0 bash model-v2x-track/routed-g6/test/reproduce_r3_validation.sh
# The inference commands are independent: `python common/tools/reproduce_validation.py model-v2x-track/routed-g6 --tag r3 --jobs`
# prints them, one per line, for running several GPUs at once.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/../../.."      # the repository root (portable)
source common/env/activate.sh
mkdir -p model-v2x-track/routed-g6/validation/output/repro_r3
[ -s model-v2x-track/routed-g6/validation/output/repro_r3/pvrcnnpp-g1v3_tta_val.json ] || python common/tools/pcdet_predict.py model-v2x-track/pvrcnnpp-g1v3 --ckpt model-v2x-track/pvrcnnpp-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split val --postprocess model-v2x-track/pvrcnnpp-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-v2x-track/routed-g6/validation/output/repro_r3/pvrcnnpp-g1v3_tta_val.json
[ -s model-v2x-track/routed-g6/validation/output/repro_r3/pvrcnnpp-g1v3_tta_valB.json ] || python common/tools/pcdet_predict.py model-v2x-track/pvrcnnpp-g1v3 --ckpt model-v2x-track/pvrcnnpp-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split valB --postprocess model-v2x-track/pvrcnnpp-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-v2x-track/routed-g6/validation/output/repro_r3/pvrcnnpp-g1v3_tta_valB.json
[ -s model-v2x-track/routed-g6/validation/output/repro_r3/pvrcnnpp-ros-g1v3_tta_val.json ] || python common/tools/pcdet_predict.py model-v2x-track/pvrcnnpp-ros-g1v3 --ckpt model-v2x-track/pvrcnnpp-ros-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split val --postprocess model-v2x-track/pvrcnnpp-ros-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-v2x-track/routed-g6/validation/output/repro_r3/pvrcnnpp-ros-g1v3_tta_val.json
[ -s model-v2x-track/routed-g6/validation/output/repro_r3/pvrcnnpp-ros-g1v3_tta_valB.json ] || python common/tools/pcdet_predict.py model-v2x-track/pvrcnnpp-ros-g1v3 --ckpt model-v2x-track/pvrcnnpp-ros-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split valB --postprocess model-v2x-track/pvrcnnpp-ros-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-v2x-track/routed-g6/validation/output/repro_r3/pvrcnnpp-ros-g1v3_tta_valB.json
[ -s model-v2x-track/routed-g6/validation/output/repro_r3/pointpillars-ut_tta_val.json ] || python common/tools/pcdet_predict.py model-v2x-track/pointpillars-ut --ckpt model-v2x-track/pointpillars-ut/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split val --postprocess model-v2x-track/pointpillars-ut/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-v2x-track/routed-g6/validation/output/repro_r3/pointpillars-ut_tta_val.json
[ -s model-v2x-track/routed-g6/validation/output/repro_r3/pointpillars-ut_tta_valB.json ] || python common/tools/pcdet_predict.py model-v2x-track/pointpillars-ut --ckpt model-v2x-track/pointpillars-ut/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split valB --postprocess model-v2x-track/pointpillars-ut/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-v2x-track/routed-g6/validation/output/repro_r3/pointpillars-ut_tta_valB.json
[ -s model-v2x-track/routed-g6/validation/output/repro_r3/voxelrcnn-gblobs-g1v3_tta_val.json ] || python common/tools/pcdet_predict.py model-v2x-track/voxelrcnn-gblobs-g1v3 --ckpt model-v2x-track/voxelrcnn-gblobs-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split val --postprocess model-v2x-track/voxelrcnn-gblobs-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-v2x-track/routed-g6/validation/output/repro_r3/voxelrcnn-gblobs-g1v3_tta_val.json
[ -s model-v2x-track/routed-g6/validation/output/repro_r3/voxelrcnn-gblobs-g1v3_tta_valB.json ] || python common/tools/pcdet_predict.py model-v2x-track/voxelrcnn-gblobs-g1v3 --ckpt model-v2x-track/voxelrcnn-gblobs-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split valB --postprocess model-v2x-track/voxelrcnn-gblobs-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-v2x-track/routed-g6/validation/output/repro_r3/voxelrcnn-gblobs-g1v3_tta_valB.json
[ -s model-v2x-track/routed-g6/validation/output/repro_r3/voxelrcnn-ros-g1v4_tta_val.json ] || python common/tools/pcdet_predict.py model-v2x-track/voxelrcnn-ros-g1v4 --ckpt model-v2x-track/voxelrcnn-ros-g1v4/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split val --postprocess model-v2x-track/voxelrcnn-ros-g1v4/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-v2x-track/routed-g6/validation/output/repro_r3/voxelrcnn-ros-g1v4_tta_val.json
[ -s model-v2x-track/routed-g6/validation/output/repro_r3/voxelrcnn-ros-g1v4_tta_valB.json ] || python common/tools/pcdet_predict.py model-v2x-track/voxelrcnn-ros-g1v4 --ckpt model-v2x-track/voxelrcnn-ros-g1v4/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split valB --postprocess model-v2x-track/voxelrcnn-ros-g1v4/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-v2x-track/routed-g6/validation/output/repro_r3/voxelrcnn-ros-g1v4_tta_valB.json
[ -s model-v2x-track/routed-g6/validation/output/repro_r3/voxelrcnn-ros-g1v3_tta_val.json ] || python common/tools/pcdet_predict.py model-v2x-track/voxelrcnn-ros-g1v3 --ckpt model-v2x-track/voxelrcnn-ros-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split val --postprocess model-v2x-track/voxelrcnn-ros-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-v2x-track/routed-g6/validation/output/repro_r3/voxelrcnn-ros-g1v3_tta_val.json
[ -s model-v2x-track/routed-g6/validation/output/repro_r3/voxelrcnn-ros-g1v3_tta_valB.json ] || python common/tools/pcdet_predict.py model-v2x-track/voxelrcnn-ros-g1v3 --ckpt model-v2x-track/voxelrcnn-ros-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split valB --postprocess model-v2x-track/voxelrcnn-ros-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-v2x-track/routed-g6/validation/output/repro_r3/voxelrcnn-ros-g1v3_tta_valB.json
python common/tools/reproduce_validation.py model-v2x-track/routed-g6 --tag r3 --score
